python3 << 'EOF'
with open('AGENTS.md', 'r') as f:
    lines = f.readlines()

# Find the table start
in_table = False
skills = []
for i, line in enumerate(lines):
    if line.startswith('| Skill | Path | When to use |'):
        in_table = True
        continue
    if in_table and line.startswith('| :---'):
        continue
    if in_table and line.startswith('| '):
        # Extract skill name
        parts = line.split('|')
        if len(parts) >= 2:
            skill_name = parts[1].strip()
            skills.append((i+1, skill_name))
    elif in_table and not line.startswith('| '):
        break

print(f"Total skills in table: {len(skills)}")

# Check sorting
prev = ""
issues = []
for line_num, name in skills:
    if name < prev:
        issues.append((line_num, prev, name))
    prev = name

if issues:
    print("SORTING ISSUES:")
    for line_num, prev_name, curr_name in issues:
        print(f"  Line {line_num}: '{prev_name}' > '{curr_name}'")
else:
    print("All skills are properly sorted!")
EOF

